## 2️⃣ Update `Settings.jsx`

Below is a minimal example that

1. **Does not touch the header** – it only touches components inside Settings.
2. Shows a toggle switch for dark mode.
3. Keeps the “Save” button functional on mobile.

```jsx
import React, { useContext, useState, useEffect } from 'react';
import { ThemeContext } from '../contexts/ThemeContext';
import { useMutation } from '@tanstack/react-query';
import api from '../api'; // Assumed fetch wrapper
import './Settings.css';   // Make sure you import the CSS

export default function Settings() {
  const { theme, toggleTheme } = useContext(ThemeContext);

  // Example local form state (replace with your real forms)
  const [form, setForm] = useState({ /* ... */ });

  // Mutation to hit `/api/settings` – replace URL & payload
  const mutation = useMutation({
    mutationFn: () => api.post('/settings', form),
    onSuccess: () => {
      alert('Settings saved!');
    },
    onError: () => {
      alert('An error occurred.');
    },
  });

  // Save button handler
  const handleSave = (e) => {
    e.preventDefault();
    mutation.mutate();
  };

  // Mobile‑friendly design: button takes full width
  const isMobile = window.innerWidth < 600; // simple check

  return (
    <div className="settings-page">
      {/* Dark‑mode toggle */}
      <div className="toggle-wrapper">
        <label className="switch">
          <input
            type="checkbox"
            checked={theme === 'dark'}
            onChange={toggleTheme}
          />
          <span className="slider round"></span>
        </label>
        <span className="toggle-label">
          {theme === 'light' ? 'Light mode' : 'Dark mode'}
        </span>
      </div>

      {/* Your existing form fields go here */}
      <form onSubmit={handleSave} className="settings-form">
        {/* … fields … */}
        <button
          type="submit"
          className={`save-btn ${isMobile ? 'full-width' : ''}`}
          disabled={mutation.isLoading}
        >
          {mutation.isLoading ? 'Saving...' : 'Save'}
        </button>
      </form>
    </div>
  );
}
```

### Why it works on mobile

- The **`.full-width`** class is added only when the viewport is narrower than 600 px, which gives the button a block display.
- `e.preventDefault()` guards against accidental form submissions on touch devices.

